function progressApprenticeship(s,date){const a=s.apprentice;if(!a||a.status!=='ACTIVE'||!isWorkday(date))return;const weekday=new Date(`${date}T12:00:00Z`).getUTCDay();if(weekday===a.schoolWeekday){a.schoolDays++;pushEvent(s,1,'BERUFSSCHULE',`${a.name}: Berufsschultag, angerechnet auf die Ausbildungszeit.`,null,date);}else{const trainer=s.employees.find(e=>e.id===a.trainerId),room=getSpaceUse(s);if(trainer&&availability(s,trainer,date)&&!(trainer.training?.remainingDays>0)&&room.officePeople<=room.officeCapacity&&room.staffPeople<=room.staffCapacity)a.practiceDays++;}const start=new Date(`${a.startedAt}T12:00:00Z`),now=new Date(`${date}T12:00:00Z`),elapsed=(now.getUTCFullYear()-start.getUTCFullYear())*12+now.getUTCMonth()-start.getUTCMonth();a.progressMonths=Math.min(a.durationMonths,Math.max(0,elapsed));if(a.progressMonths>=a.durationMonths){a.status='COMPLETED';s.employees.push({id:'MA-AZ-01',name:a.name,role:'Fachkraft Metalltechnik · Zerspanungstechnik',skill:['PREP','PACK','CNC'],monthlyCost:3600,morale:75,productivityBonus:.02,competencies:{fach:68,methoden:65,sozial:70,individual:72},maxPotential:{fach:88,methoden:84,sozial:86,individual:90},qualifications:{machines:['CNC-01'],trainer:false},vacationDaysUsed:0,sickUntil:null,vacationPlan:[]});s.network.companyReputation=Math.min(100,s.network.companyReputation+3);pushEvent(s,1,'AUSBILDUNG_ABGESCHLOSSEN',`${a.name} hat die Ausbildung abgeschlossen und wird als Fachkraft übernommen.`,null,date);}}
