function processAcceptance(s){for(const o of s.orders){if(!o.deliveredAt||o.acceptedAt||o.rejectedAt)continue;if(o.acceptanceDue<=s.date){o.acceptedAt=s.date;o.status='ABGENOMMEN';pushEvent(s,6,'AUTOMATISCHE_ABNAHME',`${o.id}: nach fünf Arbeitstagen abgenommen.`,o.id);}if(o.acceptedAt&&!o.invoiceReadyAt){o.invoiceReadyAt=s.date;o.status='ABGERECHNET';pushEvent(s,7,'RECHNUNG_BEREIT',`${o.id}: automatische Rechnung bereit.`,o.id);}}}
