export function hireEmployee(s,role='production'){const room=getSpaceUse(s);if(room.workplacePeople>=room.workplaceCapacity)return null;const n=(s.employees||[]).filter(e=>!e.isOwner).length+1,cnc=role==='cnc',e={id:`MA-V2-${String(n).padStart(2,'0')}`,name:cnc?`CNC-Fachkraft ${n}`:`Fertigungsmitarbeiter ${n}`,role:cnc?'CNC-Fachkraft':'Fertigung und Versand',skill:cnc?['CNC','QUALITY','PREP','PACK']:['PREP','PACK'],monthlyCost:cnc?3900:3300,morale:75,motivation:75,productivityBonus:0,competencies:{fach:cnc?78:63,methoden:68,sozial:70,individual:70},maxPotential:{fach:92,methoden:88,sozial:88,individual:88},qualifications:{machines:cnc?['CNC-01']:[],trainer:false},vacationDaysUsed:0,vacationDaysTaken:[],sickUntil:null,vacationPlan:[]};s.employees.push(e);pushEvent(s,1,'EINSTELLUNG',`${e.name} eingestellt; monatliche Personalkosten im Szenario ${e.monthlyCost} €.`,null);return e;}
export function negotiateTemporaryAgency(s,offerId=s.agencyOfferSelection||'balanced'){if(s.temporaryAgencyContract)return false;const offer=TEMP_AGENCY_OFFERS.find(x=>x.id===offerId);if(!offer)return false;s.temporaryAgencyContract={...offer,agreedAt:s.date,legacy:false};pushEvent(s,1,'ZEITARBEITSVERTRAG','Agenturvertrag '+offer.label+' vereinbart: Grundpreis '+offer.monthlyBaseFee.toFixed(2)+' €/Monat bei Einsatz, Stundenpreis '+offer.hourlyRate.toFixed(2)+' €/h.');return true;}
export function bookTemporaryWorker(s,{date=s.date,skill='CNC',hours=8,orderId=null,count=1,duration='day'}){if(!s.temporaryAgencyContract)return null;const agency=TEMP_AGENCIES.find(a=>a.id===s.temporaryAgencyContract.id);if(!agency)return null;let firstWorkday=date,calendarGuard=0;while(!isWorkday(firstWorkday)&&calendarGuard++<14)firstWorkday=addCalendarDays(firstWorkday,1);if(!isWorkday(firstWorkday))return null;const wanted=Math.max(1,Math.min(agency.pool.length,Math.floor(Number(count)||1))),days=duration==='month'?20:duration==='week'?5:1,dates=[];for(let d=firstWorkday;dates.length<days;d=addCalendarDays(d,1))if(isWorkday(d))dates.push(d);const reserved=new Set(s.temporaryWorkers.filter(w=>dates.includes(w.date)&&w.agencyId===agency.id).map(w=>w.workerId||w.id)),eligible=agency.pool.filter(w=>w.skill.includes(skill)&&!reserved.has(w.id));if(eligible.length<wanted)return null;const terms=s.temporaryAgencyContract,selected=eligible.slice(0,wanted),created=[];for(const day of dates){const space=getSpaceUse(s,day),availableSlots=Math.max(0,space.workplaceCapacity-space.workplacePeople);if(availableSlots<wanted)return null;}for(const worker of selected){for(const day of dates){const entry={...clone(worker),id:worker.id,workerId:worker.id,name:worker.name,role:`Zeitarbeit · ${agency.name}`,temp:true,agencyId:agency.id,agencyName:agency.name,skill:[...worker.skill],morale:worker.motivation,date:day,bookedHours:Math.min(8,Math.max(1,Number(hours))),hourlyRate:Number(terms.hourlyRate),agencyBaseFeeMonthly:Number(terms.monthlyBaseFee),agencyContractId:terms.id};s.temporaryWorkers.push(entry);created.push(entry);}}pushEvent(s,1,'ZEITARBEITSBUCHUNG',`${wanted} Person(en) von ${agency.name} für ${duration==='month'?'einen Monat':duration==='week'?'eine Woche':'einen Tag'} ab ${firstWorkday} in die Personalplanung aufgenommen; keine Auftragsbindung.`,null);return created[0]||null;}
export function scheduleVacationDay(s,employeeId,date){const e=s.employees.find(x=>x.id===employeeId);if(!e||!isWorkday(date)||e.vacationDaysUsed+(e.vacationPlan||[]).filter(d=>d>=s.date).length>=20)return false;if(!e.vacationPlan.includes(date)){e.vacationPlan.push(date);pushEvent(s,1,'URLAUB',`${e.name}: Urlaub am ${date} vorgemerkt.`,null,date);}return true;}
export function shipOrder(s,id){const o=s.orders.find(x=>x.id===id&&x.status==='VERSANDBEREIT'&&x.producedAt&&!x.deliveredAt);if(!o)return false;o.deliveredAt=s.date;o.shippedAt=s.date;o.acceptanceDue=addWorkdays(s.date,5);o.status='GELIEFERT';if(o.dueDate&&s.date>o.dueDate&&!o.latePenaltyApplied){const lateDays=Math.ceil((new Date(`${s.date}T12:00:00Z`)-new Date(`${o.dueDate}T12:00:00Z`))/86400000);o.lateDays=lateDays;o.latePenaltyApplied=true;s.network.companyReputation=Math.max(20,s.network.companyReputation-Math.min(10,Math.max(1,lateDays*.3)));const customer=s.network.customers.find(x=>x.id===o.customer);if(customer)customer.relationship=Math.max(20,customer.relationship-Math.min(5,lateDays*.5));pushEvent(s,5,'LIEFERUNG_VERSPAETET',`${o.id}: Versand ${lateDays} Kalendertage nach Szenario-Liefertermin; Ruf- und Kundenbindungswirkung angewendet.`,o.id);}pushEvent(s,5,'VERSAND',`${o.id}: ${o.quantity} Stück aus dem Fertigwarenlager versendet; Abnahmefrist bis ${o.acceptanceDue}.`,o.id);return true;}
export function acceptOrder(s,o){if(!o?.deliveredAt||o.acceptedAt||o.rejectedAt)return false;o.acceptedAt=s.date;o.status='ABGENOMMEN';pushEvent(s,6,'ABNAHME',`${o.id}: ausdrücklich abgenommen.`,o.id);o.invoiceReadyAt=s.date;o.status='ABGERECHNET';pushEvent(s,7,'RECHNUNG_BEREIT',`${o.id}: Rechnung bereit.`,o.id);return true;}
export function rejectOrder(s,o){if(!o?.deliveredAt||o.acceptedAt||o.rejectedAt)return false;o.rejectedAt=s.date;o.status='ABLEHNUNG_IN_KLÄRUNG';pushEvent(s,6,'ABLEHNUNG',`${o.id}: Abnahme abgelehnt.`,o.id);return true;}
export function startRework(s,id){const o=s.orders.find(x=>x.id===id&&x.status==='ABLEHNUNG_IN_KLÄRUNG');if(!o||o.invoiceReadyAt||(o.reworkAttempts||0)>=1)return false;o.reworkAttempts=1;o.rejectedAt=null;o.deliveredAt=null;o.acceptanceDue=null;o.acceptedAt=null;o.status='NACHARBEIT';o.operations.push({id:50,name:'Nacharbeit und erneute Qualitätsprüfung',resource:'MA-CNC',skill:'QUALITY',totalHours:4});pushEvent(s,1,'NACHARBEIT_GESTARTET',`${o.id}: einmalige Nacharbeit (4 Qualitätsstunden) eingeplant; Abnahmefrist beginnt nach erneuter Lieferung.`,o.id);return true;}
export function closePaidOrder(s,id,date=s.date){const o=s.orders.find(x=>x.id===id);if(!o||!o.invoiceReadyAt||o.closedAt)return false;o.closedAt=date;o.status='ABGESCHLOSSEN';s.annualStats.ordersClosed++;s.network.companyReputation=Math.min(100,s.network.companyReputation+.35);const customer=s.network.customers.find(x=>x.id===o.customer);if(customer)customer.relationship=Math.min(100,customer.relationship+1);pushEvent(s,8,'KUNDENZAHLUNG',`${o.id}: vollständig bezahlt und geschlossen; Unternehmensruf und Kundenbindung verbessert.`,id,date);return true;}
export function getCurrentOperation(o){return o?.operations[o.operationIndex]||null;}
export function formatDate(d,options={}){return new Intl.DateTimeFormat('de-DE',{day:'2-digit',month:'short',year:options.year?'numeric':undefined,timeZone:'UTC'}).format(new Date(`${d}T12:00:00Z`));}
export function getWeekLabel(d){const date=new Date(`${d}T12:00:00Z`),mon=new Date(date);mon.setUTCDate(mon.getUTCDate()-(mon.getUTCDay()+6)%7);const sun=new Date(mon);sun.setUTCDate(sun.getUTCDate()+6);const f=x=>new Intl.DateTimeFormat('de-DE',{day:'2-digit',month:'short',timeZone:'UTC'}).format(x);return `${f(mon)} – ${f(sun)}`;}
export function getSpaceUse(s,date=s.date){const stock=s.inventory,workday=isWorkday(date),finishedGoods=(s.orders||[]).filter(o=>o.producedAt&&!o.deliveredAt&&!o.closedAt).reduce((sum,o)=>sum+Math.max(0,Number(o.quantity)||0)*.015,0),warehouse=stock.steel*.008+stock.aluminium*.01+stock.parts*.004+finishedGoods,employees=workday?s.employees.filter(e=>availability(s,e,date)&&!(e.training?.remainingDays>0)).length:0,temps=workday?s.temporaryWorkers.filter(w=>w.date===date&&w.bookedHours>0).length:0,weekday=new Date(`${date}T12:00:00Z`).getUTCDay(),trainer=s.employees.find(e=>e.id===s.apprentice?.trainerId),apprenticeOnsite=Boolean(workday&&s.apprentice?.status==='ACTIVE'&&weekday!==s.apprentice.schoolWeekday&&trainer&&availability(s,trainer,date)&&!(trainer.training?.remainingDays>0))?1:0,workplacePeople=employees+temps+apprenticeOnsite,officeCapacity=Math.floor(s.roomSettings.office/8),staffCapacity=Math.floor(s.roomSettings.staff/8),machineCapacity=s.facility?.machineCapacity??Math.floor(s.roomSettings.workshop/70),workshopPeopleCapacity=Math.floor(Math.max(0,s.roomSettings.workshop-s.roomSettings.machineCount*70)/8),workplaceCapacity=Math.max(0,Math.min(officeCapacity,staffCapacity,workshopPeopleCapacity));return {warehouse,finishedGoods,warehouseCapacity:s.roomSettings.warehouse,officePeople:workplacePeople,officeCapacity,staffPeople:workplacePeople,staffCapacity,workshopPeople:workplacePeople,workshopPeopleCapacity,workplacePeople,workplaceCapacity,apprenticeOnsite,machineCount:s.roomSettings.machineCount,machineCapacity,workshopArea:s.roomSettings.workshop};}
export function relocateFacility(s,facilityId,tenure){const building=FACILITIES.find(x=>x.id===facilityId);if(!building||!['rent','purchase'].includes(tenure)||s.facility?.id===facilityId)return false;s.facility={...building,tenure};Object.assign(s.roomSettings,{rent:tenure==='rent'?building.rent:0,warehouse:building.warehouse,office:building.office,staff:building.staff,workshop:building.workshop,machineCount:Math.min(s.roomSettings.machineCount,building.machineCapacity)});pushEvent(s,1,'UMZUG',`Betrieb an den Standort „${building.name}“ verlegt; Nutzung: ${tenure==='rent'?'Miete':'Kauf'}.`,null);return true;}
export function scheduleVacationWeek(s,employeeId,startDate){const e=s.employees.find(x=>x.id===employeeId);if(!e)return false;let d=startDate,added=0;const future=e.vacationPlan.filter(x=>x>=startDate).sort();if(future.length<5)return false;for(const old of future.slice(0,5))e.vacationPlan.splice(e.vacationPlan.indexOf(old),1);while(added<5){if(isWorkday(d)&&!e.vacationPlan.includes(d)){e.vacationPlan.push(d);added++;pushEvent(s,1,'URLAUB',`${e.name}: Urlaub am ${d} eingeplant.`,null,d);}d=addCalendarDays(d,1);}return true;}
